import type { Metadata } from "next";
import { company } from "@/content/company";

type PageSeoInput = {
  /** Page-specific title; " — CanCraft Beverages" is appended. Ignored when `absoluteTitle` is set. */
  title?: string;
  /** Full title used exactly as given, with no brand suffix appended (e.g. "… | CanCraft"). */
  absoluteTitle?: string;
  description: string;
  /** Canonical path, e.g. "/capabilities". */
  path: string;
  /** robots noindex, follow. Off by default — only for pages explicitly approved for it. */
  noindex?: boolean;
};

/** Sitewide social preview cards generated by app/opengraph-image.tsx and app/twitter-image.tsx. */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${company.brandName}: private label and contract beverage manufacturing`,
};
export const TWITTER_IMAGE = { ...OG_IMAGE, url: "/twitter-image" };

/** The full <title> a page renders with. */
export function resolvePageTitle({ title, absoluteTitle }: Pick<PageSeoInput, "title" | "absoluteTitle">): string {
  if (absoluteTitle) return absoluteTitle;
  if (!title) throw new Error("pageMetadata: title or absoluteTitle is required");
  return `${title} — ${company.brandName}`;
}

/**
 * Consistent per-page metadata: title, description, canonical, Open Graph/Twitter (including the
 * sitewide preview image) and optional robots noindex. `path` is resolved against the root
 * layout's metadataBase (lib/site.ts) into a full canonical/OG URL.
 *
 * The preview image is set explicitly: a page-level `openGraph`/`twitter` object replaces the one
 * inherited from the root file-based images, so without it only the home page had an og:image.
 */
export function pageMetadata({ title, absoluteTitle, description, path, noindex }: PageSeoInput): Metadata {
  const fullTitle = resolvePageTitle({ title, absoluteTitle });

  return {
    // Absolute title rather than the root layout's title.template — the template does not
    // reliably apply to the root "/" segment's own page.tsx.
    title: { absolute: fullTitle },
    description,
    alternates: {
      canonical: path,
    },
    ...(noindex ? { robots: { index: false, follow: true } } : {}),
    openGraph: {
      title: fullTitle,
      description,
      url: path,
      siteName: company.brandName,
      type: "website",
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [TWITTER_IMAGE],
    },
  };
}
